export const newGame = () => ({ board: Array(9).fill(null), turn: "X" });

export function click(game, cell) {
  if (game.board[cell]) return game;
  const board = game.board.with(cell, game.turn);
  return { board, turn: game.turn === "X" ? "O" : "X" };
}

writes.src/winner.js:
const LINES = [[0, 1, 2], [3, 4, 5], [6, 7, 8], [0, 3, 6], [1, 4, 7], [2, 5, 8], [0, 4, 8], [2, 4, 6]];

export function winner(board) {
  for (const [a, b, c] of LINES) if (board[a] && board[a] === board[b] && board[a] === board[c]) return board[a];
  return null;
}

